package com.payments.core

import kotlinx.coroutines.*
import java.nio.ByteBuffer
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong

// JNI bridge to native HSM (Hardware Security Module) for payment signing
object NativeHSM {
    init { System.loadLibrary("payment_hsm") }

    // Native methods - implemented in C via JNI
    external fun allocateSigningContext(merchantId: Long, keySlot: Int): Long
    external fun writeTransactionData(contextPtr: Long, data: ByteArray, offset: Int, length: Int): Int
    external fun finalizeSignature(contextPtr: Long, outputBuffer: ByteArray): Int
    external fun releaseContext(contextPtr: Long)
    external fun getContextState(contextPtr: Long): Int
}

data class PaymentRequest(
    val merchantId: Long,
    val amount: Long,
    val currency: String,
    val cardTokenHash: ByteArray,
    val nonce: ByteArray
)

data class SignedPayment(
    val signature: ByteArray,
    val contextId: Long
)

class PaymentSigningService {

    private val activeContexts = ConcurrentHashMap<Long, Long>() // correlationId -> nativePtr
    private val correlationCounter = AtomicLong(0)
    private val signingDispatcher = Dispatchers.IO.limitedParallelism(4)

    companion object {
        const val CTX_STATE_INITIALIZED = 0
        const val CTX_STATE_DATA_WRITTEN = 1
        const val CTX_STATE_FINALIZED = 2
        const val CTX_STATE_RELEASED = 3
        const val HSM_KEY_SLOT_PRODUCTION = 1
        const val HSM_KEY_SLOT_SANDBOX = 2
        const val MAX_TRANSACTION_SIZE = 4096
    }

    suspend fun signPayment(request: PaymentRequest): Result<SignedPayment> = withContext(signingDispatcher) {
        val correlationId = correlationCounter.incrementAndGet()
        var contextPtr: Long = 0

        try {
            // Step 1: Allocate native signing context
            val keySlot = resolveKeySlot(request.merchantId)
            contextPtr = NativeHSM.allocateSigningContext(request.merchantId, keySlot)

            if (contextPtr == 0L) {
                return@withContext Result.failure(IllegalStateException("HSM context allocation failed"))
            }

            activeContexts[correlationId] = contextPtr

            // Step 2: Serialize and write transaction data
            val transactionData = serializeTransaction(request)

            if (transactionData.size > MAX_TRANSACTION_SIZE) {
                return@withContext Result.failure(IllegalArgumentException("Transaction too large"))
            }

            // Step 3: Write data to native context with bounds
            val writeResult = writeDataChunked(contextPtr, transactionData)
            if (writeResult < 0) {
                return@withContext Result.failure(IllegalStateException("HSM write failed: $writeResult"))
            }

            // Step 4: Yield to allow cancellation check
            yield()

            // Step 5: Finalize signature
            val signatureBuffer = ByteArray(512)
            val sigLength = NativeHSM.finalizeSignature(contextPtr, signatureBuffer)

            if (sigLength <= 0) {
                return@withContext Result.failure(IllegalStateException("Signature generation failed"))
            }

            val signature = signatureBuffer.copyOf(sigLength)
            Result.success(SignedPayment(signature, correlationId))

        } catch (e: CancellationException) {
            // On cancellation, we still need to release the native context
            // But the context pointer might be used by another coroutine that
            // picked up the same correlation slot after rapid reuse
            throw e
        } finally {
            // Release native resources
            val storedPtr = activeContexts.remove(correlationId)
            if (storedPtr != null && storedPtr != 0L) {
                safeRelease(storedPtr)
            }
        }
    }

    private suspend fun writeDataChunked(contextPtr: Long, data: ByteArray): Int {
        val chunkSize = 1024
        var offset = 0

        while (offset < data.size) {
            val remaining = data.size - offset
            val currentChunk = minOf(chunkSize, remaining)

            val result = NativeHSM.writeTransactionData(contextPtr, data, offset, currentChunk)
            if (result < 0) return result

            offset += currentChunk

            // Cooperative yield between chunks - allows coroutine cancellation
            yield()
        }
        return 0
    }

    private fun safeRelease(contextPtr: Long) {
        val state = NativeHSM.getContextState(contextPtr)
        if (state != CTX_STATE_RELEASED) {
            NativeHSM.releaseContext(contextPtr)
        }
    }

    private fun resolveKeySlot(merchantId: Long): Int {
        // Production merchants use slot 1, sandbox uses slot 2
        return if (merchantId > 0) HSM_KEY_SLOT_PRODUCTION else HSM_KEY_SLOT_SANDBOX
    }

    private fun serializeTransaction(request: PaymentRequest): ByteArray {
        val buffer = ByteBuffer.allocate(MAX_TRANSACTION_SIZE)
        buffer.putLong(request.merchantId)
        buffer.putLong(request.amount)
        buffer.put(request.currency.toByteArray(Charsets.UTF_8).copyOf(4))
        buffer.put(request.cardTokenHash)
        buffer.put(request.nonce)
        buffer.flip()
        val result = ByteArray(buffer.remaining())
        buffer.get(result)
        return result
    }

    // Batch processing endpoint
    suspend fun processBatch(requests: List<PaymentRequest>): List<Result<SignedPayment>> {
        return coroutineScope {
            requests.map { request ->
                async { signPayment(request) }
            }.awaitAll()
        }
    }

    // Cleanup method for graceful shutdown
    fun shutdown() {
        activeContexts.forEach { (_, ptr) ->
            if (ptr != 0L) {
                try { NativeHSM.releaseContext(ptr) } catch (_: Exception) {}
            }
        }
        activeContexts.clear()
    }
}
